-- Nomod (UAE) Hosted Checkout gateway. Everything here is additive: no existing
-- row changes, and a shop that never enables Nomod is untouched. The gateway sits
-- behind the `nomod_payments` feature key (platform grant, default OFF) AND the
-- merchant's own enabled toggle on `shoppaymentprovider` (default OFF).

-- 1. The unguessable per-shop webhook token. It lives in the URL path
--    (/payments/webhook/nomod/<token>) and is the ONLY thing that picks the shop
--    for an incoming delivery (never anything in the payload). 32 random bytes as
--    64 hex characters, generated by the application. UNIQUE so two shops can never
--    share a URL; NULL until a merchant first opens the Nomod settings.
ALTER TABLE `shoppaymentprovider`
  ADD COLUMN `webhookToken` VARCHAR(64) NULL,
  ADD UNIQUE INDEX `shoppaymentprovider_webhookToken_key`(`webhookToken`);

-- 2. One row per Nomod checkout we created. `referenceId` is what we send as
--    reference_id (unique per Nomod account, so a retry after an expired session
--    gets a new one: "<orderId>" for the first attempt, "<orderId>-<attempt>" after).
--    The webhook maps an event to an order ONLY through (shopId, referenceId), so a
--    delivery signed for shop A can never touch shop B's order. amountMinor and
--    currency are what we ASKED Nomod to charge, frozen at creation (integer minor
--    units of the order's own currency), and what a paid event is verified against.
--    status: creating | created | paid | failed | cancelled | expired | review.
CREATE TABLE `nomodcheckout` (
    `id` INTEGER NOT NULL AUTO_INCREMENT,
    `shopId` INTEGER NOT NULL,
    `orderId` INTEGER NOT NULL,
    `attempt` INTEGER NOT NULL,
    `referenceId` VARCHAR(100) NOT NULL,
    `checkoutId` VARCHAR(100) NULL,
    `amountMinor` BIGINT NOT NULL,
    `currency` CHAR(3) NOT NULL,
    `status` VARCHAR(20) NOT NULL DEFAULT 'creating',
    `chargeId` VARCHAR(100) NULL,
    `refundedMinor` BIGINT NOT NULL DEFAULT 0,
    `reviewReason` VARCHAR(100) NULL,
    `disputedAt` DATETIME(3) NULL,
    `lastCheckedAt` DATETIME(3) NULL,
    `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    `updatedAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),

    UNIQUE INDEX `nomodcheckout_shopId_referenceId_key`(`shopId`, `referenceId`),
    UNIQUE INDEX `nomodcheckout_shopId_checkoutId_key`(`shopId`, `checkoutId`),
    INDEX `nomodcheckout_orderId_idx`(`orderId`),
    INDEX `nomodcheckout_shopId_status_createdAt_idx`(`shopId`, `status`, `createdAt`),
    PRIMARY KEY (`id`)
) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

ALTER TABLE `nomodcheckout` ADD CONSTRAINT `nomodcheckout_shopId_fkey` FOREIGN KEY (`shopId`) REFERENCES `shop`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE `nomodcheckout` ADD CONSTRAINT `nomodcheckout_orderId_fkey` FOREIGN KEY (`orderId`) REFERENCES `order`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;

-- 3. Webhook delivery dedupe, keyed by Nomod's eventId. A row is written BEFORE the
--    event is processed and `processedAt` is set after, so a delivery that dies
--    half-way is picked up again on Nomod's retry instead of being swallowed as a
--    duplicate. No payload and no customer data is stored here, only identifiers.
CREATE TABLE `nomodwebhookevent` (
    `id` INTEGER NOT NULL AUTO_INCREMENT,
    `shopId` INTEGER NOT NULL,
    `eventId` VARCHAR(100) NOT NULL,
    `eventType` VARCHAR(64) NOT NULL,
    `objectId` VARCHAR(100) NULL,
    `orderId` INTEGER NULL,
    `outcome` VARCHAR(40) NULL,
    `receivedAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    `processedAt` DATETIME(3) NULL,

    UNIQUE INDEX `nomodwebhookevent_shopId_eventId_key`(`shopId`, `eventId`),
    PRIMARY KEY (`id`)
) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

ALTER TABLE `nomodwebhookevent` ADD CONSTRAINT `nomodwebhookevent_shopId_fkey` FOREIGN KEY (`shopId`) REFERENCES `shop`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;

-- 4. Provider refund state on a return. providerRefundStatus: pending | completed |
--    failed (NULL = no provider refund was attempted, or a provider that reports no
--    state: every existing row). providerRefundKey is the deterministic
--    idempotency key sent with the refund, stored so a failed refund can be retried
--    with the SAME key and can never be applied twice.
ALTER TABLE `orderreturn`
  ADD COLUMN `providerRefundStatus` VARCHAR(20) NULL,
  ADD COLUMN `providerRefundKey` VARCHAR(64) NULL;

-- 5. PLT-1: every plan carries a planfeature row for every registered key (billing
--    test). Nomod is a payment capability, not a tier decision made here: every plan
--    is entitled, and the platform grant (override) plus the merchant's own switch
--    still decide whether it is on. Idempotent, insert-if-missing.
INSERT INTO `planfeature` (`planId`, `featureKey`, `entitled`)
SELECT p.`id`, 'nomod_payments', 1 FROM `plan` p
WHERE NOT EXISTS (
  SELECT 1 FROM `planfeature` pf WHERE pf.`planId` = p.`id` AND pf.`featureKey` = 'nomod_payments'
);
